import torch
from qwen_asr import Qwen3ForcedAligner

model = Qwen3ForcedAligner.from_pretrained(
    "Qwen/Qwen3-ForcedAligner-0.6B",
    dtype=torch.bfloat16,
    device_map="cuda:0",
    # attn_implementation="flash_attention_2",
)

import os
import json

# --- Configuration ---
chunks_dir = "/content/Alla_output"

# --- Sanity check ---
if not os.path.exists(chunks_dir):
    raise FileNotFoundError(f"Directory not found: {chunks_dir}")

print(f"📂 Processing directory: {chunks_dir}\n")

# --- Processing ---
for fname in sorted(os.listdir(chunks_dir)):
    if not (fname.endswith(".wav") and fname.startswith("chunk_")):
        continue

    base = os.path.splitext(fname)[0]
    wav_file = os.path.join(chunks_dir, fname)
    txt_file = os.path.join(chunks_dir, base + ".txt")

    if not os.path.exists(txt_file):
        print(f"⚠️ Missing text for {base}, skipping...")
        continue

    # --- Read transcript ---
    try:
        with open(txt_file, "r", encoding="utf-8") as f:
            text = f.read().strip()
    except Exception as e:
        print(f"❌ Failed reading {txt_file}: {e}")
        continue

    # --- Run alignment ---
    try:
        results = model.align(
            audio=wav_file,
            text=text,
            language="Arabic",
        )

        # --- Extract aligned words ---
        alignment_data = []

        for item in results[0].items:   # ✅ FIX HERE
            start = float(item.start_time)
            end = float(item.end_time)

            # skip broken alignments
            if end <= start:
                continue

            alignment_data.append({
                "word": item.text,
                "start": round(start, 3),
                "end": round(end, 3),
                "duration": round(end - start, 3)
            })

        # --- Optional debug (first chunk only) ---
        if base == "chunk_000":
            print("\n🔍 Sample alignment preview:")
            for w in alignment_data[:10]:
                print(w)

        # --- Save JSON ---
        json_file = os.path.join(chunks_dir, base + "_alignment.json")

        output_payload = {
            "source_file": fname,
            "transcript": text,
            "num_words": len(alignment_data),
            "words": alignment_data
        }

        with open(json_file, "w", encoding="utf-8") as f:
            json.dump(output_payload, f, ensure_ascii=False, indent=2)

        print(f"✅ Saved: {json_file}")

    except Exception as e:
        print(f"❌ Failed to align {base}: {e}")

print("\n🎉 Processing complete.")

